package com.spark.falcon.inventory.entity;
import jakarta.persistence.*;import lombok.*;import java.math.*;
@Entity @Table(name="physical_stock_count_rows",uniqueConstraints=@UniqueConstraint(name="uk_count_row_variant_batch",columnNames={"count_id","product_variant_id","product_batch_id"})) @Getter @NoArgsConstructor
public class PhysicalStockCountRow {@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="count_id",nullable=false)private PhysicalStockCount count;@Column(name="product_variant_id",nullable=false)private Long productVariantId;@Column(name="product_batch_id")private Long productBatchId;@Column(name="base_inventory_unit_id",nullable=false)private Long baseInventoryUnitId;@Column(name="system_quantity_snapshot",nullable=false,precision=19,scale=8)private BigDecimal systemQuantitySnapshot;@Column(name="counted_quantity",precision=19,scale=8)private BigDecimal countedQuantity;@Column(name="counted_unit_id")private Long countedUnitId;@Column(name="conversion_factor",precision=19,scale=8)private BigDecimal conversionFactor;@Column(name="converted_base_quantity",precision=19,scale=8)private BigDecimal convertedBaseQuantity;@Column(name="variance",precision=19,scale=8)private BigDecimal variance;@Column(name="variance_reason",length=240)private String varianceReason;@Column(name="adjustment_id")private Long adjustmentId;
 public static PhysicalStockCountRow snapshot(Long variant,Long batch,Long baseUnit,BigDecimal system){PhysicalStockCountRow r=new PhysicalStockCountRow();r.productVariantId=variant;r.productBatchId=batch;r.baseInventoryUnitId=baseUnit;r.systemQuantitySnapshot=system;return r;}void attach(PhysicalStockCount c){count=c;}public void refreshSystemQuantitySnapshot(BigDecimal system){if(system==null||system.signum()<0)throw new IllegalArgumentException("System Quantity Snapshot must be non-negative");systemQuantitySnapshot=system.setScale(8,RoundingMode.HALF_UP);if(convertedBaseQuantity!=null)variance=convertedBaseQuantity.subtract(systemQuantitySnapshot);}public void record(BigDecimal entered,Long unit,BigDecimal factor,String reason){if(entered==null||entered.signum()<0||factor==null||factor.signum()<=0)throw new IllegalArgumentException("Valid non-negative count and positive conversion are required");countedQuantity=entered;countedUnitId=unit;conversionFactor=factor;convertedBaseQuantity=entered.multiply(factor).setScale(8,RoundingMode.HALF_UP);variance=convertedBaseQuantity.subtract(systemQuantitySnapshot);varianceReason=reason;}public void linkAdjustment(Long id){if(adjustmentId!=null)throw new IllegalStateException("Count variance already posted");adjustmentId=id;}
}
